import copy
import unittest
from dataclasses import dataclass

from unique import stable_unique


@dataclass
class EqualItem:
    value: int


class StableUniqueTests(unittest.TestCase):
    def test_empty_returns_new_list(self):
        items = []
        result = stable_unique(items)
        self.assertEqual(result, [])
        self.assertIsNot(result, items)

    def test_first_occurrences_preserve_order(self):
        self.assertEqual(stable_unique([3, 1, 3, 2, 1, 4, 2]), [3, 1, 2, 4])

    def test_lists_dicts_and_sets(self):
        self.assertEqual(stable_unique([[1], {"a": 2}, {3}, [1], {3}, {"a": 2}, []]), [[1], {"a": 2}, {3}, []])

    def test_nested_unhashable_items(self):
        self.assertEqual(stable_unique([[{"a": [1, 2]}], [{"a": [1, 2]}], [{"a": [2, 1]}]]), [[{"a": [1, 2]}], [{"a": [2, 1]}]])

    def test_equal_different_types(self):
        self.assertEqual(stable_unique([1, True, 1.0, 0, False, 0.0, "1"]), [1, 0, "1"])

    def test_returns_first_equal_object(self):
        first = EqualItem(2)
        equal = EqualItem(2)
        other = EqualItem(3)
        result = stable_unique([first, equal, other, first])
        self.assertEqual(result, [first, other])
        self.assertIs(result[0], first)
        self.assertIs(result[1], other)

    def test_generator_input(self):
        self.assertEqual(stable_unique(value % 3 for value in range(10)), [0, 1, 2])

    def test_input_is_not_mutated(self):
        items = [[1], {"a": [2]}, [1], {"a": [2]}]
        original = copy.deepcopy(items)
        result = stable_unique(items)
        self.assertEqual(items, original)
        result.append("new")
        self.assertEqual(items, original)

    def test_all_unique_and_all_equal(self):
        self.assertEqual(stable_unique([None, "", [], {}, ()]), [None, "", [], {}, ()])
        self.assertEqual(stable_unique([[], [], []]), [[]])


if __name__ == "__main__":
    unittest.main()
